entries[39738] = { ["name"] = "Donnerbräus Starkbier", ["text"] = "Questgegenstand\nDauer: 2 tagen (Realzeit)\nBenötigt Stufe 70\nBenutzen: Stellt im Verlauf von 30 sec insgesamt 7200 Mana wieder her. Ihr müsst beim Trinken sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Trinken verbringt, werdet Ihr wahrscheinlich kräftig wachsen." }
entries[39739] = { ["name"] = "Wolvarbeeren", ["text"] = "Questgegenstand\nBenutzen: Mixt die Wolvarbeeren mit Donnerbräus Starkbier, um das geheime Gebräu der Wildherzen zu erhalten." }
